1	// Package server exposes the frozen public surface of VaultGrid.
2	//
3	// In addition to process health, it serves the storage-pool and capacity
4	// reservation HTTP API described in README.md. The exported surface
5	// (Handler, Version, VAULTGRID_ADDR handling) stays backward compatible.
6	package server
7	
8	import (
9		"encoding/json"
10		"io"
11		"net/http"
12		"regexp"
13		"strings"
14	)
15	
16	// Version is the release identifier.
17	const Version = "0.1.0"
18	
19	// idPattern restricts every client-supplied id: 1..64 letters, digits,
20	// dots, underscores or hyphens.
21	var idPattern = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)
22	
23	type health struct {
24		Status  string `json:"status"`
25		Service string `json:"service"`
26		Version string `json:"version"`
27	}
28	
29	// Handler returns the HTTP surface served by VaultGrid.
30	func Handler() http.Handler {
31		mux := http.NewServeMux()
32		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
33			if r.Method != http.MethodGet {
34				w.Header().Set("Allow", http.MethodGet)
35				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
36				return
37			}
38			w.Header().Set("Content-Type", "application/json; charset=utf-8")
39			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "vaultgrid", Version: Version})
40		})
41		mux.HandleFunc("/", newStore().route)
42		return mux
43	}
44	
45	const storagePoolPath = "/v1/storage-pools"
46	
47	// route dispatches every non-healthz request. Paths it does not recognise
48	// answer 404/not_found; recognised paths with the wrong verb answer 405.
49	func (s *store) route(w http.ResponseWriter, r *http.Request) {
50		if r.URL.Path != storagePoolPath && !strings.HasPrefix(r.URL.Path, storagePoolPath+"/") {
51			writeError(w, http.StatusNotFound, "not_found")
52			return
53		}
54	
55		parts := splitPoolPath(r.URL.Path)
56		for _, seg := range parts {
57			if seg == "" {
58				writeError(w, http.StatusNotFound, "not_found")
59				return
60			}
61		}
62		switch {
63		case len(parts) == 0:
64			switch r.Method {
65			case http.MethodGet:
66				s.listPools(w)
67			case http.MethodPost:
68				s.createPool(w, r)
69			default:
70				methodNotAllowed(w, http.MethodGet, http.MethodPost)
71			}
72		case len(parts) == 1:
73			switch r.Method {
74			case http.MethodGet:
75				s.getPool(w, parts[0])
76			case http.MethodDelete:
77				s.deletePool(w, parts[0])
78			default:
79				methodNotAllowed(w, http.MethodGet, http.MethodDelete)
80			}
81		case len(parts) == 2 && parts[1] == "reservations":
82			if r.Method != http.MethodPost {
83				methodNotAllowed(w, http.MethodPost)
84				return
85			}
86			s.createReservation(w, r, parts[0])
87		case len(parts) == 3 && parts[1] == "reservations":
88			if r.Method != http.MethodDelete {
89				methodNotAllowed(w, http.MethodDelete)
90				return
91			}
92			s.deleteReservation(w, parts[0], parts[2])
93		default:
94			writeError(w, http.StatusNotFound, "not_found")
95		}
96	}
97	
98	// splitPoolPath splits the tail after /v1/storage-pools into path segments.
99	func splitPoolPath(path string) []string {
100		rest := strings.TrimPrefix(path, storagePoolPath)
101		if rest == "" {
102			return nil
103		}
104		segments := strings.Split(rest, "/")
105		// Drop the single empty segment introduced by the leading slash, but
106		// keep trailing/inner empty segments so the caller can reject them 404.
107		if segments[0] == "" {
108			segments = segments[1:]
109		}
110		return segments
111	}
112	
113	func writeJSON(w http.ResponseWriter, status int, v any) {
114		w.Header().Set("Content-Type", "application/json; charset=utf-8")
115		w.WriteHeader(status)
116		_ = json.NewEncoder(w).Encode(v)
117	}
118	
119	func writeError(w http.ResponseWriter, status int, code string) {
120		writeJSON(w, status, map[string]any{"error": map[string]string{"code": code}})
121	}
122	
123	func methodNotAllowed(w http.ResponseWriter, allowed ...string) {
124		w.Header().Set("Allow", strings.Join(allowed, ", "))
125		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
126	}
127	
128	// decodeRequest parses exactly one JSON value, rejecting unknown fields and
129	// any trailing content so malformed bodies cannot partially apply.
130	func decodeRequest(r *http.Request, v any) bool {
131		dec := json.NewDecoder(r.Body)
132		dec.DisallowUnknownFields()
133		if err := dec.Decode(v); err != nil {
134			return false
135		}
136		var extra json.RawMessage
137		if err := dec.Decode(&extra); err != io.EOF {
138			return false
139		}
140		return true
141	}
142

