import (
	"encoding/json"
	"io"
	"net/http"
	"regexp"
	"strings"
)

// Version is the release identifier.
const Version = "0.1.0"

// idPattern restricts every client-supplied id: 1..64 letters, digits,
// dots, underscores or hyphens.
