type pool struct {
	id           string
	devices      []deviceInput
	rawCapacity  int64
	reservations map[string]reservation
}

// volume is a capacity allocation inside a pool with an optional exclusive
// node binding. generation is bumped on every binding state change.
type volume struct {
	id         string
	poolID     string
	sizeBytes  int64
	generation int64
	binding    string // "" when unbound
}

func (p *pool) reservationBytes() int64 {
	var total int64
	for _, r := range p.reservations {
		total += r.bytes
	}
	return total
}

// viewWith fills the capacity fields of the pool view, counting explicit
// reservations together with the volume sizes handed in by the caller.
func (p *pool) viewWith(volumeBytes int64) poolView {
	devices := make([]deviceView, len(p.devices))
	for i, d := range p.devices {
		devices[i] = deviceView{ID: d.ID, CapacityBytes: d.CapacityBytes, FaultDomain: d.FaultDomain}
	}
	allocated := p.reservationBytes() + volumeBytes
	return poolView{
		ID:               p.id,
		Devices:          devices,
		RawCapacityBytes: p.rawCapacity,
		AllocatedBytes:   allocated,
		AvailableBytes:   p.rawCapacity - allocated,
	}
}

